// src/components/KalmTrace.tsx
//
// Landing-page hero (owner brief, 5 Oct 2026): the Mumbai night skyline,
// traced from a Pexels photograph (free for commercial use, edits allowed)
// in the site's own palette: black line on white, with the sage accent. It has
// no card or border: the picture sits directly on the page and its edges fade
// into the background, so it reads as part of the site.
//
// Not the photo itself: the tower outlines were traced by hand from it and the
// lit windows read out of it, so every window sits where it does in the real
// picture. Tall towers get a heavier line, the brightest windows a soft sage
// halo, and a sage haze lifts off the horizon behind the buildings.
//
// In order: each tower is drawn in one fine line, left to right, and fills in;
// the lattice mast and cranes follow; the windows light up in a wave; the haze
// rises; the rippled reflection settles in the water; then (kalm) appears.
// Plays once, about 3.5 seconds. Reduced motion: the finished picture.
//
// Pure SVG and CSS: no image file, so there is no photo to download.

import Wordmark from '@/components/Wordmark';

const CSS = `
@keyframes kt-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes kt-fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes kt-word { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
@keyframes kt-glint { 0%, 100% { opacity: 0.78; } 50% { opacity: 1; } }
.kt-line { fill: none; stroke: var(--ink); stroke-opacity: 0.9; stroke-width: 0.9; stroke-dasharray: 1; animation: kt-draw 1.1s ease-in-out both; }
.kt-tall { stroke-width: 1.6; stroke-opacity: 1; }
.kt-fill { fill: var(--paper-dim); stroke: none; animation: kt-fade 0.8s ease-out both; }
.kt-win { stroke-linecap: round; animation: kt-fade 0.9s ease-out both; }
.kt-halo { fill: none; animation: kt-fade 1.2s ease-out 2s both; }
.kt-haze { animation: kt-fade 1.8s ease-out 2s both; }
.kt-refl { animation: kt-fade 1.6s ease-out 2.6s both; }
.kt-word { animation: kt-word 0.9s ease-out 3s both; }
.kt-glint { animation: kt-glint 4.5s ease-in-out 4.5s infinite; }
@media (prefers-reduced-motion: reduce) {
  .kt-line { animation: none; stroke-dasharray: none; }
  .kt-fill, .kt-win, .kt-halo, .kt-haze, .kt-refl, .kt-word, .kt-glint { animation: none; }
}
`;

